 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private Future<?> task;private volatile java.net.HttpURLConnection active;private int generation;private TextView status;private EditText search;private Spinner groups;private ListView list;private Button link,file;private AlertDialog dialog;private List<IptvPlaylist.Channel> channels=Collections.emptyList(),shown=new ArrayList<>();private final List<String> names=new ArrayList<>();private ArrayAdapter<String> rows;private boolean loading,started;
