 private void pick(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),740);}catch(Exception e){status.setText("Seletor de arquivos indisponível.");}}
