 private void url(){EditText input=new EditText(this);Ui.input(input);input.setSingleLine(true);input.setHint("https://servidor/lista.m3u");input.setContentDescription("Endereço HTTPS da lista IPTV");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);dialog=new AlertDialog.Builder(this).setTitle("Adicionar lista IPTV").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Abrir",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=input.getText().toString().trim();if(!IptvPlaylist.stream(value,"").startsWith("https://")){input.setError("Use HTTPS; para listas HTTP, importe o arquivo M3U.");return;}dialog.dismiss();read(()->IptvStore.download(this,value,connection->active=connection));}));dialog.show();}
 private void refresh(){String base=getSharedPreferences("iptv",0).getString("base","");read(()->base.isEmpty()?IptvStore.read(this):IptvStore.download(this,base,connection->active=connection));}
 private void remove(){new AlertDialog.Builder(this).setTitle("Remover lista do Onda?").setMessage("Apaga somente a lista importada. O arquivo original permanece no celular.").setNegativeButton("Cancelar",null).setPositiveButton("Remover",(d,w)->{generation++;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();IptvStore.file(this).delete();getSharedPreferences("iptv",0).edit().clear().apply();loading=false;show(Collections.emptyList());}).show();}
 private void read(Read action){int request=++generation;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();loading=true;link.setEnabled(false);file.setEnabled(false);status.setText("Lendo lista IPTV…");task=worker.submit(()->{try{List<IptvPlaylist.Channel> result=action.run();handler.post(()->{if(isDestroyed()||request!=generation)return;loading=false;show(result);});}catch(Exception e){handler.post(()->{if(isDestroyed()||request!=generation)return;loading=false;link.setEnabled(true);file.setEnabled(true);String message=e instanceof java.io.IOException?e.getMessage():"Não foi possível ler a lista.";status.setText((message==null?"Falha ao abrir a lista.":message.replaceAll("https?://\\S+","[endereço]"))+" A lista anterior foi mantida.");});}});}
 private void show(List<IptvPlaylist.Channel> value){channels=value;link.setEnabled(true);file.setEnabled(true);TreeSet<String> unique=new TreeSet<>();for(IptvPlaylist.Channel channel:channels)if(!channel.group.isEmpty())unique.add(channel.group);ArrayList<String> all=new ArrayList<>();all.add("Todos os grupos");all.addAll(unique);groups.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,all));filter();}
 private void filter(){if(rows==null)return;String query=SearchText.normalize(search.getText());String group=groups.getSelectedItemPosition()>0?String.valueOf(groups.getSelectedItem()):"";shown.clear();names.clear();for(IptvPlaylist.Channel channel:channels)if((group.isEmpty()||group.equals(channel.group))&&channel.search.contains(query)){shown.add(channel);names.add(channel.name+(channel.group.isEmpty()?"":"\n"+channel.group));}rows.notifyDataSetChanged();if(!loading)status.setText(channels.isEmpty()?"Nenhuma lista importada. Use Adicionar link ou Abrir M3U.":shown.size()+" de "+channels.size()+" canais • toque para assistir");}
 @Override protected void onStart(){super.onStart();started=true;if(channels.isEmpty()&&!loading)read(()->IptvStore.read(this));else filter();}
 @Override protected void onStop(){started=false;if(loading){generation++;if(task!=null)task.cancel(true);java.net.HttpURLConnection old=active;if(old!=null)old.disconnect();loading=false;link.setEnabled(true);file.setEnabled(true);}super.onStop();}
